def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
    mark = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (0, 2)]
    # Project each rectangle row horizontally; markers on a side block projection from that side.
    for r in range(r0, r1 + 1):
        left_blocked = any(rr == r and cc < c0 for rr, cc in mark)
        right_blocked = any(rr == r and cc > c1 for rr, cc in mark)
        if not left_blocked:
            for c in range(c0):
                out[r][c] = 2
        if not right_blocked:
            for c in range(c1 + 1, w):
                out[r][c] = 2
    # Project columns vertically with the same blocker rule.
    for c in range(c0, c1 + 1):
        top_blocked = any(cc == c and rr < r0 for rr, cc in mark)
        bottom_blocked = any(cc == c and rr > r1 for rr, cc in mark)
        if not top_blocked:
            for r in range(r0):
                out[r][c] = 2
        if not bottom_blocked:
            for r in range(r1 + 1, h):
                out[r][c] = 2
    for r, c in mark:
        out[r][c] = grid[r][c]
    return out
